mapper.select:
SELECT cr.counseling_id, -- 상담 ID cr.student_id, -- 학생 ID su.name AS student_name, -- 학생 이름 s.student_no, -- 학생 관리번호 cr.parent_id, -- 학부모 ID pu.name AS parent_name, -- 학부모 이름 cr.teacher_id, -- 강사 ID tu.name AS teacher_name, -- 강사 이름 cr.counseling_date, -- 상담일 cr.counseling_type, -- 상담 유형 cr.content, -- 상담 내용 cr.visibility_code, -- 공개 범위 cr.created_by, -- 등록자 ID cu.name AS created_by_name, -- 등록자 이름 cr.created_at -- 등록일시 FROM counseling_records cr JOIN students s ON s.student_id = cr.student_id JOIN users su ON su.user_id = s.user_id LEFT JOIN parents p ON p.parent_id = cr.parent_id LEFT JOIN users pu ON pu.user_id = p.user_id LEFT JOIN teachers t ON t.teacher_id = cr.teacher_id LEFT JOIN users tu ON tu.user_id = t.user_id JOIN users cu ON cu.user_id = cr.created_by
cr.student_id = #{studentId}
AND cr.parent_id = #{parentId}
AND cr.teacher_id = #{teacherId}
AND cr.visibility_code = #{visibilityCode}
AND ( cr.visibility_code = 'SHARED' OR cr.created_by = #{viewerUserId} OR EXISTS ( SELECT 1 FROM teachers viewer_teacher WHERE viewer_teacher.teacher_id = cr.teacher_id AND viewer_teacher.user_id = #{viewerUserId} ) )
ORDER BY cr.counseling_date DESC, cr.counseling_id DESC

mapper.delete:
DELETE FROM counseling_records
WHERE counseling_id = #{counselingId}

    AND created_by = #{viewerUserId}
